/bin/bash -lc "python - <<'PY'
import requests
for repo in ['biocontainers/python','biocontainers/r-base','biocontainers/pandas','biocontainers/scipy','biocontainers/openpyxl','biocontainers/pyxlsb']:
 resp=requests.get('https://quay.io/api/v1/repository/'+repo+'/tag/',params={'limit':20,'onlyActiveTags':True},timeout=60)
 print('\\n',repo,'status',resp.status_code)
 if resp.ok:
  tags=resp.json().get('tags',[])
  print([t.get('name') for t in tags[:20]])
 else: print(resp.text[:200])
PY"

